import express from 'express';
import fse from 'fs-extra';
import { mkdtemp, rm } from 'fs/promises';
import { createServer } from 'http';
import { tmpdir } from 'os';
import { join } from 'path';
import { createPackageRoute, EMPTY_ISLAND_MODULE, PACKAGE_ROUTE_PREFIX, } from '../local-preview/packages/serve.js';
const BUILD = 'a'.repeat(32);
describe('package route', () => {
    let root;
    let server;
    let base;
    let state;
    beforeEach(async () => {
        root = await mkdtemp(join(tmpdir(), 'packages-serve-'));
        const buildsDir = join(root, '.mintlify', 'packages');
        await fse.outputFile(join(buildsDir, BUILD, 'client/islands/i0123456789abcdef.js'), 'export {}');
        await fse.outputFile(join(buildsDir, BUILD, 'client/chunk-AB12.js'), 'export const a = 1;');
        await fse.outputFile(join(buildsDir, BUILD, 'manifest.json'), '{"islands":{}}');
        await fse.outputFile(join(buildsDir, BUILD, 'server/islands/x.js'), 'secret');
        await fse.outputFile(join(root, 'outside.js'), 'outside');
        state = { enabled: true, buildsDir };
        const app = express();
        app.use(PACKAGE_ROUTE_PREFIX, createPackageRoute(() => state));
        app.use((_req, res) => {
            res.status(418).send('next');
        });
        server = createServer(app);
        await new Promise((resolve) => server.listen(0, resolve));
        base = `http://127.0.0.1:${server.address().port}${PACKAGE_ROUTE_PREFIX}`;
    });
    afterEach(async () => {
        await new Promise((resolve) => server.close(resolve));
        await rm(root, { recursive: true, force: true });
    });
    it('serves client files from a build under a dot folder', async () => {
        const res = await fetch(`${base}/${BUILD}/client/islands/i0123456789abcdef.js`);
        expect(res.status).toBe(200);
        expect(res.headers.get('content-type')).toMatch(/javascript/);
        expect(res.headers.get('x-content-type-options')).toBe('nosniff');
        expect(res.headers.get('cache-control')).toBe('no-cache');
        expect(await res.text()).toBe('export {}');
        expect((await fetch(`${base}/${BUILD}/client/chunk-AB12.js`)).status).toBe(200);
    });
    it('never serves the manifest, server bundles or paths outside client', async () => {
        for (const path of [
            `${BUILD}/manifest.json`,
            `${BUILD}/server/islands/x.js`,
            `${BUILD}/client/../manifest.json`,
            `${BUILD}/client/%2e%2e/manifest.json`,
            `${BUILD}/client/..%2f..%2f..%2f..%2foutside.js`,
            `..%2f..%2foutside.js`,
        ]) {
            const res = await fetch(`${base}/${path}`);
            expect(res.status, path).toBe(404);
            expect(await res.text(), path).not.toMatch(/secret|outside|islands/);
        }
    });
    it('answers a missing island entry with a module that renders nothing', async () => {
        const res = await fetch(`${base}/pending/client/islands/i0000000000000000.js`);
        expect(res.status).toBe(200);
        expect(res.headers.get('content-type')).toMatch(/javascript/);
        expect(res.headers.get('cache-control')).toBe('no-store');
        expect(await res.text()).toBe(EMPTY_ISLAND_MODULE);
        const mod = await import(`data:text/javascript,${encodeURIComponent(EMPTY_ISLAND_MODULE)}`);
        expect(mod).toMatchObject({ hydrate: expect.any(Function) });
    });
    it('falls through to Next when packages are off', async () => {
        state = { ...state, enabled: false };
        const res = await fetch(`${base}/${BUILD}/client/islands/i0123456789abcdef.js`);
        expect(res.status).toBe(418);
    });
});
